-- ============================================================
-- SEED EXT 6: Módulo 23 — Advanced Modals (ex 203-300)
-- Blocos 71-82 | 98 exercícios
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'advanced-modals';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo advanced-modals não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 71: Perfect modals — must have (deduction about past) (8 ex)
  (cid,71,203,'gap_fill','The sudden collapse of the institution _____ (must/shock) observers who had regarded it as a model of good governance — the sheer speed of the decline _____ (must/leave) even seasoned analysts struggling to explain what went wrong.','must have shocked / must have left',NULL,'''Must have + past participle'' = strong deduction about past; both ''must have shocked'' and ''must have left'' express logical inference from past evidence.','medium'),
  (cid,71,204,'gap_fill','The discrepancy between the projected and actual outcomes _____ (must/arise) from a fundamental flaw in the modelling assumptions rather than from measurement error — the magnitude of the gap _____ (can/not/account/passive) for by random variation alone.','must have arisen / cannot be accounted',NULL,'''Must have arisen'' = past deduction; ''cannot be accounted for by'' = present modal + passive.','hard'),
  (cid,71,205,'gap_fill','The researchers _____ (must/overlook) several critical confounders when designing the study — had they _____ (not/do) so, their conclusions _____ (might/be) considerably more reliable than they ultimately proved to be.','must have overlooked / not done / might have been',NULL,'''Must have overlooked'' (past deduction); ''had they not done so, might have been'' (inverted third conditional).','hard'),
  (cid,71,206,'gap_fill','The policy _____ (must/design/passive) with the best of intentions — there _____ (can/be) little doubt that its architects believed it would succeed — but good intentions _____ (cannot/substitute) for careful empirical analysis of likely effects.','must have been designed / can be / cannot substitute',NULL,'''Must have been designed'' = past passive deduction; ''can be little doubt'' = present epistemic; ''cannot substitute'' = present deontic.','hard'),
  (cid,71,207,'gap_fill','The _____ (extent) of the problem _____ (must/know/passive) to senior management long before it _____ (become) public — documents subsequently _____ (release/passive) under freedom of information legislation _____ (suggest) that concerns _____ (raise/passive) as early as three years before the crisis.','extent / must have been known / became / released / suggest / had been raised',NULL,'''Must have been known'' = past deduction passive; ''had been raised'' = past perfect (earlier in timeline).','hard'),
  (cid,71,208,'gap_fill','Something _____ (must/go) seriously wrong in the consultation process — had it _____ (function/passive) as intended, the level of public opposition that _____ (subsequently/emerge) _____ (should/not/come) as a surprise to the authorities.','must have gone / functioned / subsequently emerged / should not have come',NULL,'''Must have gone'' (past deduction); ''had it functioned'' (inverted conditional); ''should not have come'' (past criticism/expectation).','hard'),
  (cid,71,209,'gap_fill','The _____ (author) _____ (must/be/familiar) with the broader _____ (literature) when writing this section — the _____ (argument) closely _____ (parallel) several _____ (develop → noun) that _____ (appear) in other _____ (publication) around the same time, though _____ (no) _____ (direct/citation) _____ (provide/passive).','author / must have been familiar / literature / argument / parallels / developments / appeared / publications / no / direct citation / is provided',NULL,'''Must have been familiar'' (past deduction); ''parallels...appeared'' (presents and past describing text); note complex structure.','hard'),
  (cid,71,210,'multiple_choice','Which sentence CORRECTLY uses ''must have'' for past deduction?','The anomaly must have been introduced during the data cleaning phase, since earlier versions of the dataset do not show the same pattern.','[''The anomaly must be introduced during the data cleaning phase.'',''The anomaly must have been introduced during the data cleaning phase, since earlier versions of the dataset do not show the same pattern.'',''The anomaly must have introduce during the data cleaning phase.'',''The anomaly must introduced during the data cleaning phase.'']','Option B: ''must have been + past participle'' = past deduction passive. ''Must be'' (A) = present; ''must have introduce'' (C) = wrong; ''must introduced'' (D) = ungrammatical.','easy'),

  -- BLOCK 72: Perfect modals — should have / ought to have (past criticism) (8 ex)
  (cid,72,211,'gap_fill','The government _____ (should/consult) more widely before implementing the policy — had it _____ (do) so, it _____ (might/avoid) many of the _____ (unforeseen) _____ (consequence) that subsequently _____ (emerge).','should have consulted / done / might have avoided / unforeseen / consequences / emerged',NULL,'''Should have consulted'' = past criticism/regret; ''had it done so, might have avoided'' = inverted third conditional.','medium'),
  (cid,72,212,'gap_fill','The researchers _____ (ought/acknowledge) the limitations of their methodology more explicitly — in _____ (fail/gerund) to do so, they _____ (may/expose/passive) themselves to legitimate criticism of a kind that _____ (can/easily/avoid/passive) with minimal additional care.','ought to have acknowledged / failing / may have exposed / could have been avoided',NULL,'''Ought to have acknowledged'' = past moral obligation; ''may have exposed'' = past possibility; ''could have been avoided'' = past counterfactual.','hard'),
  (cid,72,213,'gap_fill','The board _____ (should/not/proceed) with the appointment without conducting a more thorough vetting process — the _____ (problem) that subsequently _____ (come) to light _____ (should/detect/passive) _____ (well) before the decision _____ (take/passive).','should not have proceeded / problems / came / should have been detected / well / was taken',NULL,'''Should not have proceeded'' (past criticism) + ''should have been detected'' (past passive criticism).','hard'),
  (cid,72,214,'gap_fill','The _____ (analyst) _____ (should/be/aware) that the _____ (data) _____ (could/interpret/passive) in multiple ways and _____ (ought/present) _____ (alternative) _____ (reading) alongside their preferred _____ (interpretation) — in _____ (not/do) so, they _____ (may/mislead/passive) readers unfamiliar with the _____ (methodological) _____ (issue) at _____ (stake).','analyst / should have been aware / data / could be interpreted / ought to have presented / alternative / readings / interpretation / not doing / may have misled / methodological / issues / stake',NULL,'''Should have been aware'' + ''ought to have presented'' + ''may have misled'' = three perfect/other modals in academic critique.','hard'),
  (cid,72,215,'gap_fill','The _____ (oversight) _____ (body) _____ (should/intervene) earlier — by the time it _____ (finally/act), the problems _____ (already/entrench/passive) to such a degree that _____ (effective) _____ (remedy/passive) _____ (prove) _____ (far) more _____ (difficult) than it _____ (need/be).','oversight / body / should have intervened / finally acted / had already been entrenched / effective remediation proved / far / difficult / needed to be',NULL,'''Should have intervened earlier'' (past criticism); ''by the time it acted'' (past perfect sequence); ''than it needed to be'' (comparison).','hard'),
  (cid,72,216,'gap_fill','Critics _____ (argue) that the government _____ (ought/not/commit) _____ (itself) to the _____ (international) _____ (agreement) without first _____ (secure/gerund) the _____ (domestic) _____ (legislative) _____ _____ (base) needed to _____ (implement) it — the _____ (difficulty) that subsequently _____ (arise) _____ (could/largely/avoid/passive).','argue / ought not to have committed / itself / international / agreement / securing / domestic / legislative / base / implement / difficulties / arose / could largely have been avoided',NULL,'''Ought not to have committed'' (past criticism/regret) + ''could largely have been avoided'' (past counterfactual).','hard'),
  (cid,72,217,'gap_fill','The _____ (study) _____ (ought/include) a _____ (control) _____ (group) to _____ (allow) _____ (causal) _____ (inference) — without one, the _____ (claim) that the _____ (intervention) _____ (cause) the _____ (observe/passive) _____ (improvement) _____ (cannot/sustain/passive) with the _____ (degree) of _____ (confidence) the _____ (author) _____ _____ (assert).','study / ought to have included / control / group / allow / causal / inference / claim / intervention / caused / observed / improvement / cannot be sustained / degree / confidence / authors / assert',NULL,'''Ought to have included'' (past criticism); ''cannot be sustained'' (present modal + passive); academic methods critique.','hard'),
  (cid,72,218,'multiple_choice','Which sentence CORRECTLY uses ''should have'' to express past criticism?','The committee should have sought independent legal advice before authorizing the transaction.','[''The committee should seek independent legal advice before authorizing the transaction.'',''The committee should have sought independent legal advice before authorizing the transaction.'',''The committee should has sought independent legal advice before authorizing the transaction.'',''The committee should have been seeking independent legal advice before authorizing the transaction.'']','Option B: ''should have + past participle (sought)'' = standard past criticism. ''Should seek'' (A) = future advice; ''should has'' (C) = ungrammatical; ''should have been seeking'' (D) = past progressive (implies ongoing — less natural here).','easy'),

  -- BLOCK 73: Perfect modals — could have / might have (8 ex)
  (cid,73,219,'gap_fill','A more _____ (cautious) _____ (approach) _____ (might/prevent) the crisis entirely — or at least _____ (might/limit) its _____ (severity) to a degree that _____ (allow) recovery within a more _____ (reasonable) _____ (timeframe).','cautious / approach / might have prevented / might have limited / severity / allowed / reasonable / timeframe',NULL,'''Might have prevented / limited'' = past counterfactual possibilities (unrealized alternatives).','medium'),
  (cid,73,220,'gap_fill','The outcome _____ (could/be) significantly different had the _____ (initial) _____ (assumption) _____ (prove) correct — as it _____ (turn) out, the _____ (flaw) in the original _____ (model) _____ (could/never/detect/passive) using the _____ (method) that _____ (employ/passive) at the time.','could have been / initial / assumptions / proved / turned / flaw / model / could never have been detected / methods / were employed',NULL,'''Could have been'' (past counterfactual); ''could never have been detected'' (past counterfactual passive).','hard'),
  (cid,73,221,'gap_fill','The _____ (failure) of the _____ (initiative) _____ (might/avoid/passive) had the _____ (implementation) _____ (plan) _____ (design/passive) with greater _____ (attention) to the _____ (local) _____ (context) — alternative _____ (design) _____ (might/produce) more _____ (durable) _____ (result).','failure / initiative / might have been avoided / implementation / plan / been designed / attention / local / context / designs / might have produced / durable / results',NULL,'''Might have been avoided'' (past passive counterfactual); ''might have produced'' (past counterfactual).','hard'),
  (cid,73,222,'gap_fill','The _____ (evidence) _____ (could/interpret/passive) in more than one way — while the _____ (author) _____ (elect) to _____ (favor) the _____ (interpretation) that _____ (align) with their theoretical _____ (framework), they _____ (acknowledge) that _____ (alternative) _____ (reading) _____ (might/emerge) from the same _____ (dataset).','evidence / could be interpreted / author / elected / favor / interpretation / aligns / framework / acknowledge / alternative / readings / might have emerged',NULL,'''Could be interpreted'' (present epistemic modal + passive); ''might have emerged'' (past counterfactual).','hard'),
  (cid,73,223,'gap_fill','Had the _____ (consultation) _____ (conduct/passive) more _____ (rigorously), it _____ (might/surface) _____ (concern) that _____ (subsequently) _____ _____ _____ _____ (prove/to/be) central to the _____ (controversy) — _____ (better) _____ (early) _____ (warning) _____ (might/allow) _____ _____ (timely) _____ (corrective) _____ (action) to _____ _____ (take/passive).','consultation / been conducted / rigorously / might have surfaced / concerns / subsequently / proved to be / controversy / better / early / warning / might have allowed / timely / corrective / action / be taken',NULL,'''Had the consultation been conducted'' (inverted conditional); ''might have surfaced''; ''might have allowed action to be taken.''','hard'),
  (cid,73,224,'gap_fill','The _____ (policy) _____ (might/achieve) its _____ (objective) had it _____ (accompany/passive) by adequate _____ (resource) and genuine _____ (political) _____ (will) — in the _____ (absence) of _____ (both), the _____ (outcome) _____ (could/predict/passive) by anyone _____ (familiar) with the _____ (relevant) _____ (literature).','policy / might have achieved / objectives / been accompanied / resources / political / will / absence / both / outcome / could have been predicted / familiar / relevant / literature',NULL,'''Might have achieved'' (counterfactual); ''could have been predicted'' (past passive counterfactual).','hard'),
  (cid,73,225,'gap_fill','With a _____ (more) _____ (comprehensive) _____ (dataset), the _____ (researcher) _____ (might/draw) far more _____ (robust) _____ (conclusion) and _____ _____ (might/be) in a _____ (stronger) _____ (position) to make _____ (specific) _____ (policy) _____ (recommendation) — as it _____ (stand/passive), the _____ (analysis) _____ (can/support) only _____ (tentative) _____ (inference).','more / comprehensive / dataset / researcher / might have drawn / robust / conclusions / might have been / stronger / position / specific / policy / recommendations / stands / analysis / can support / tentative / inferences',NULL,'''Might have drawn...might have been in a stronger position'' (counterfactual); ''can support only tentative inferences'' (present limitation).','hard'),
  (cid,73,226,'multiple_choice','Which sentence CORRECTLY uses ''could have'' as a past counterfactual?','The situation could have been avoided had the relevant authorities acted on the early warning signals they received.','[''The situation could avoid had the relevant authorities acted on the early warning signals.'',''The situation could have avoided had the relevant authorities acted on the early warning signals.'',''The situation could have been avoided had the relevant authorities acted on the early warning signals they received.'',''The situation could been avoided had the relevant authorities acted on the early warning signals.'']','Option C: ''could have been avoided'' = past passive counterfactual; ''had the authorities acted'' = inverted third conditional.','easy'),

  -- BLOCK 74: Perfect modals — would have / needn't have (8 ex)
  (cid,74,227,'gap_fill','The _____ (controversy) _____ (would/not/arise) had the _____ (organization) been more _____ (transparent) about its _____ (decision/make → noun) _____ (process) from the _____ (outset) — _____ (greater) _____ (openness) _____ (would/allow) _____ (stakeholder) to _____ (raise) _____ _____ (concern) at a _____ (stage) when _____ (they) _____ (could/still/address/passive).','controversy / would not have arisen / organization / transparent / decision-making / process / outset / greater / openness / would have allowed / stakeholders / raise / concerns / stage / they / could still have been addressed',NULL,'''Would not have arisen'' (third conditional); ''would have allowed'' (third conditional); ''could still have been addressed'' (past counterfactual passive).','hard'),
  (cid,74,228,'gap_fill','The outcome _____ (would/be) very different had the _____ (initial) _____ (condition) _____ (differ) in the _____ _____ (ways) _____ _____ _____ (suggest/passive) by _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/most/optimistic/reading/of/the/available/evidence).','would have been / initial / conditions / differed / ways / suggested / by the most optimistic reading of the available evidence',NULL,'''Would have been very different had the conditions differed'' = third conditional with inverted ''had.''','hard'),
  (cid,74,229,'gap_fill','The researchers _____ (needn''t/conduct) a _____ (second) _____ (round) of _____ (data) _____ _____ (collection) — _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/additional/data/prove/to/be/largely/redundant) with what _____ (already/collect/passive) in the _____ (first) _____ (phase).','needn''t have conducted / the additional data proved to be largely redundant / had already been collected / first / phase',NULL,'''Needn''t have conducted'' = unnecessary action (was done but didn''t need to be); ''had already been collected'' (past perfect).','hard'),
  (cid,74,230,'gap_fill','The _____ (team) _____ (would/succeed) had it _____ (receive) the _____ (logistical) _____ (support) it _____ (request) — without that _____ (support), even the most _____ (well-design/passive) _____ (initiative) _____ (would/struggle) to _____ (achieve) its _____ (aim).','team / would have succeeded / received / logistical / support / requested / without / well-designed / initiative / would struggle / achieve / aims',NULL,'''Would have succeeded had it received'' (third conditional); ''would struggle'' (present second conditional consequence).','hard'),
  (cid,74,231,'gap_fill','You _____ (needn''t/repeat) the entire _____ (analysis) — a _____ (targeted) _____ (examination) of the _____ (problematic) _____ _____ (data/point) _____ (would/suffice) and _____ (would/save) _____ (considerable) _____ (time) and _____ (resource) for other _____ (priority).','needn''t have repeated / analysis / targeted / examination / problematic / data points / would suffice / would save / considerable / time / resources / priorities',NULL,'''Needn''t have repeated'' = criticism of unnecessary action; ''would suffice / save'' = present counterfactual.','hard'),
  (cid,74,232,'gap_fill','The _____ _____ (program) _____ (would/have/a/far/greater) _____ (impact) had it _____ (target/passive) at the _____ (population) most _____ (affect/passive) by the _____ (problem) rather than at a _____ (broader) _____ _____ (constituency) whose _____ (need) were _____ (already/address/passive) by existing _____ (provision).','program / would have had a far greater / impact / been targeted / population / affected / problem / broader / constituency / needs / already being addressed / provision',NULL,'''Would have had far greater impact had it been targeted'' (third conditional passive); ''already being addressed'' (past progressive passive).','hard'),
  (cid,74,233,'gap_fill','The _____ (government) _____ (needn''t/issue) such _____ (elaborate) _____ (guidance) — a _____ (brief) _____ (statement) of _____ (principle) _____ (would/prove) sufficient in _____ (most) _____ (case), and the _____ (time) _____ _____ (spend/passive/on) _____ (detail) _____ _____ (elaboration) _____ (might/better/employ/passive) _____ (elsewhere).','government / needn''t have issued / elaborate / guidance / brief / statement / principles / would have proved / cases / time / spent on / detailed / elaboration / might have been better employed / elsewhere',NULL,'''Needn''t have issued'' + ''would have proved sufficient'' + ''might have been better employed'' = three advanced modals.','hard'),
  (cid,74,234,'multiple_choice','Which sentence CORRECTLY uses ''needn''t have''?','The team needn''t have prepared three separate versions of the report — the committee ultimately requested only the executive summary.','[''The team needn''t prepared three separate versions of the report.'',''The team needn''t have prepare three separate versions of the report.'',''The team needn''t have prepared three separate versions of the report — the committee ultimately requested only the executive summary.'',''The team need not prepared three separate versions of the report.'']','Option C: ''needn''t have + past participle'' = unnecessary completed action. ''Needn''t prepared'' (A) = ungrammatical; ''needn''t have prepare'' (B) = ungrammatical; ''need not prepared'' (D) = wrong form.','easy'),

  -- BLOCK 75: Epistemic vs deontic modality in academic contexts (8 ex)
  (cid,75,235,'gap_fill','[Epistemic] The _____ (pattern) _____ (may/indicate) that the _____ (relationship) between _____ (governance) _____ (quality) and _____ (economic) _____ (performance) is _____ (more) _____ (complex) than _____ (previously) _____ (assume/passive). [Deontic] Researchers _____ (must/conduct) _____ (rigorous) _____ (comparative) _____ (study) before _____ (draw/gerund) _____ (definitive) _____ (conclusion).','may indicate / governance / quality / economic / performance / previously / assumed / must conduct / rigorous / comparative / study / drawing / definitive / conclusions',NULL,'''May indicate'' = epistemic (expressing possibility/uncertainty); ''must conduct'' = deontic (expressing obligation).','medium'),
  (cid,75,236,'gap_fill','[Epistemic] The _____ (anomaly) _____ (might/explain/passive) by _____ (uncontrolled) _____ (confound) not _____ _____ _____ (account/passive/for) in the _____ (original) _____ (design). [Deontic] Future _____ (study) _____ (should/address) this _____ (limitation) by _____ _____ _____ (incorporate/more/comprehensive) _____ (control) _____ (variable).','anomaly / might be explained / uncontrolled / confounders / accounted for / original / design / studies / should address / incorporating more comprehensive / control / variables',NULL,'''Might be explained'' = epistemic (possible explanation); ''should address'' = deontic (recommendation/obligation).','medium'),
  (cid,75,237,'gap_fill','The _____ (finding) _____ (could/represent) a _____ (genuine) _____ (substantive) _____ (effect) or _____ (might/simply/reflect/passive) a _____ (measurement) _____ (artifact) — the _____ (available) _____ (evidence) _____ (cannot/resolve) this _____ (ambiguity), and _____ _____ (further) _____ (investigation) _____ (will/require/passive).','findings / could represent / genuine / substantive / effect / might simply be reflected / measurement / artifact / available / evidence / cannot resolve / ambiguity / further / investigation / will be required',NULL,'''Could represent / might be reflected'' = epistemic alternatives; ''cannot resolve'' = epistemic/deontic boundary; ''will be required'' = necessity.','hard'),
  (cid,75,238,'gap_fill','[Epistemic] These _____ (result) _____ (suggest) that the _____ (effect) _____ (may/be) _____ (context-dependent) and _____ (may/not/generalize/passive) _____ (beyond) the _____ _____ _____ (specific/population/study). [Deontic] _____ (Caution) _____ _____ (must/therefore/exercise/passive) in _____ _____ _____ (extrapolate/these/finding) to _____ (other) _____ (setting).','results / suggest / effect / may be / context-dependent / may not be generalized / beyond / specific population studied / Caution / must therefore be exercised / extrapolating these findings / other / settings',NULL,'''May be context-dependent / may not be generalized'' = epistemic; ''must be exercised'' = deontic (obligation).','hard'),
  (cid,75,239,'gap_fill','The _____ (decline) in _____ (civic) _____ (engagement) _____ (could/attribute/passive) to _____ (several) _____ _____ _____ _____ (competing/mechanism/that) _____ _____ _____ _____ (cannot/yet/distinguish/passive) _____ (empirically) — researchers _____ (should/not/conclude) that any _____ _____ (single) _____ (factor) _____ (must/be) _____ (decisive) without _____ (more/rigorous) _____ (test).','decline / civic / engagement / could be attributed / several / competing mechanisms that / cannot yet be distinguished / empirically / should not conclude / single / factor / must be / decisive / more rigorous / testing',NULL,'''Could be attributed'' (epistemic); ''cannot yet be distinguished'' (epistemic impossibility); ''should not conclude'' (deontic); ''must be decisive'' (epistemic deduction — but here it is what should NOT be concluded).','hard'),
  (cid,75,240,'gap_fill','[Mixed] While the _____ (correlation) _____ (observed) is _____ (robust) across _____ (multiple) _____ (specification), it _____ (may/not/necessarily/imply) _____ _____ _____ _____ (causation) — researchers _____ (must/resist) the _____ _____ (temptation) to _____ (treat) _____ (correlation) as _____ _____ (evidence/of) _____ _____ _____ (causal/relationship) in the _____ (absence) of _____ _____ (appropriate) _____ _____ _____ (identification/strategy).','correlation / observed / robust / multiple / specifications / may not necessarily imply / causation / must resist / temptation / treat / correlation / evidence of / causal relationships / absence / appropriate / identification strategy',NULL,'''May not necessarily imply'' = epistemic; ''must resist'' = deontic; correlation ≠ causation in research methodology.','hard'),
  (cid,75,241,'gap_fill','The _____ (asymmetry) in the _____ (data) _____ (might/reflect) genuine _____ (structural) _____ (difference) between the two _____ (group), but it _____ (could/also/be) a _____ _____ (statistical) _____ (artifact) of _____ (the) _____ (sampling) _____ (procedure) — researchers _____ (should/report) both _____ (possibility) rather than _____ _____ _____ _____ (prematurely/commit/themselves/to) _____ (one) _____ (interpretation).','asymmetry / data / might reflect / structural / differences / groups / could also be / statistical / artifact / sampling / procedure / should report / possibilities / prematurely committing themselves to / one / interpretation',NULL,'''Might reflect / could also be'' = epistemic alternatives; ''should report'' = deontic (best practice recommendation).','hard'),
  (cid,75,242,'multiple_choice','In the sentence ''The pattern may indicate a structural shift in governance behavior,'' the modal ''may'' is best described as:','epistemic — expressing the writer''s uncertainty about whether the pattern actually indicates a structural shift.','[''deontic — expressing an obligation on the part of the pattern'',''epistemic — expressing the writer''s uncertainty about whether the pattern actually indicates a structural shift.'',''dynamic — expressing an ability of the pattern'',''deontic — giving permission for the pattern to indicate a shift'']','Option B: epistemic modality expresses the speaker/writer''s degree of certainty about a proposition. ''May'' here = possible interpretation, not obligation or permission.','medium'),

  -- BLOCK 76: Modal progressive (must be/should be/can't be + -ing) (8 ex)
  (cid,76,243,'gap_fill','The _____ (indicators) _____ (suggest) that the _____ (economy) _____ (must/slow) — _____ (if) the _____ (trend) _____ (confirm/passive) in the _____ (next) _____ (quarter), policymakers _____ (will/need) to _____ (respond) with _____ (appropriate) _____ (fiscal) _____ (measure).','indicators / suggest / economy / must be slowing / if / trend / is confirmed / next / quarter / will need / respond / appropriate / fiscal / measures',NULL,'''Must be slowing'' = present progressive with epistemic ''must'' = strong deduction about present ongoing activity.','medium'),
  (cid,76,244,'gap_fill','The _____ (committee) _____ (can''t/consider) _____ (all) the _____ (relevant) _____ (evidence) in such a _____ (compressed) _____ (timeframe) — the _____ (quality) of _____ (its) _____ (deliberation) _____ (must/suffer) as a result, however _____ _____ _____ _____ (well-intentioned/its/member/may/be).','committee / can''t be considering / all / relevant / evidence / compressed / timeframe / quality / deliberations / must be suffering / well-intentioned its members may be',NULL,'''Can''t be considering'' = present modal progressive (negative deduction); ''must be suffering'' = positive deduction about ongoing state.','hard'),
  (cid,76,245,'gap_fill','Given the _____ _____ (complexity/of) the _____ (challenge), the _____ (team) _____ (must/work) under _____ (considerable) _____ (pressure) — it _____ (cannot/easy/find) it _____ _____ (straightforward) to _____ (maintain) _____ _____ (quality) at this _____ (pace) of _____ (output).','complexity of / challenge / team / must be working / considerable / pressure / cannot be finding it / straightforward / maintain / quality / pace / output',NULL,'''Must be working under pressure'' + ''cannot be finding it straightforward'' = present modal progressives (deductions about present state).','hard'),
  (cid,76,246,'gap_fill','The _____ (discrepancy) between the _____ _____ (stated/position) and the _____ (actual) _____ (behavior) _____ (suggest) that something _____ (must/go) _____ _____ (wrong) in the _____ (translation) from _____ (policy) _____ (design) to _____ _____ _____ _____ _____ _____ (operational/implementation) — someone _____ (should/monitor) the _____ (situation) and _____ (report) _____ (on) it _____ (immediately).','discrepancy / stated position / actual / behavior / suggests / must be going / wrong / translation / policy / design / operational implementation / should be monitoring / situation / report / immediately',NULL,'''Must be going wrong'' (epistemic progressive deduction); ''should be monitoring'' (deontic progressive = ongoing obligation).','hard'),
  (cid,76,247,'gap_fill','If the _____ (authority) _____ (still/not/respond) after three _____ (formal) _____ _____ _____ (request/submit/passive), they _____ (must/encounter) _____ (significant) _____ (internal) _____ _____ (capacity/constraint) — or, _____ (alternatively), the _____ (issue) _____ (may/not/receive) the _____ _____ (internal/priority) that its _____ (urgency) _____ (demand).','authority / is still not responding / formal / requests submitted / must be encountering / significant / internal / capacity constraints / alternatively / issue / may not be receiving / internal priority / urgency / demands',NULL,'''Must be encountering'' + ''may not be receiving'' = two epistemic progressive deductions about present ongoing situations.','hard'),
  (cid,76,248,'gap_fill','The _____ _____ (organization) _____ (should/invest) _____ _____ _____ _____ _____ (far/more/heavily/in/training) than it currently _____ _____ _____ _____ _____ _____ _____ _____ (is) — the _____ _____ (level) of _____ _____ _____ _____ _____ (capability/that/its/staff) _____ _____ _____ _____ (currently/demonstrate) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (suggests/that/this/area/has/not/receive/passive) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/degree/of/strategic/attention/that/it/deserve).','organization / should be investing / far more heavily in training / is / level / capability that its staff / currently demonstrate / suggests that this area has not received / the degree of strategic attention that it deserves',NULL,'''Should be investing far more heavily'' = deontic progressive (ongoing obligation); ''has not received the degree of attention it deserves.''','hard'),
  (cid,76,249,'gap_fill','The _____ _____ (fact/that) the _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (data/continue/to/diverge/from/theoretical/expectation) _____ _____ _____ (suggests/that) _____ _____ _____ (either) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (the/theory/must/rest/on/faulty/assumption) or the _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (measurement/instrument/must/be/capture/passive/something/other/than/the/intended/construct).','fact that / data continue to diverge from theoretical expectations / suggests that / either / the theory must be resting on faulty assumptions / measurement instrument must be capturing something other than the intended construct',NULL,'''Must be resting on'' + ''must be capturing'' = two epistemic progressive deductions about present ongoing states.','hard'),
  (cid,76,250,'multiple_choice','Which sentence CORRECTLY uses the modal progressive to express a present deduction?','The project team must be struggling with the data integration issues given that no update has been submitted in over two weeks.','[''The project team must struggle with data integration issues.'',''The project team must have struggled with data integration issues.'',''The project team must be struggling with the data integration issues given that no update has been submitted in over two weeks.'',''The project team must struggled with data integration issues.'']','Option C: ''must be struggling'' = modal progressive expressing deduction about an ongoing present state based on observed evidence.','easy'),

  -- BLOCK 77: Semi-modals — need to, have to, be supposed to, be bound to (8 ex)
  (cid,77,251,'gap_fill','Researchers _____ (have/to) _____ (navigate) a _____ _____ (complex) _____ (balance) between the _____ (need/to) _____ (produce) _____ _____ _____ _____ (novel/and/publishable/finding) and the _____ (equally) _____ (important) _____ (obligation/to) _____ _____ _____ _____ _____ _____ _____ _____ _____ (maintain/the/highest/possible/standard) of _____ _____ _____ (methodological/rigor).','have to / navigate / complex / balance / need to / produce / novel and publishable findings / equally / important / obligation to / maintain the highest possible standards / methodological rigor',NULL,'''Have to navigate'' = obligation/necessity (semi-modal); ''need to produce'' = semi-modal expressing need; ''obligation to maintain'' = noun-based.','medium'),
  (cid,77,252,'gap_fill','The _____ (reform) _____ (be/supposed/to) _____ _____ _____ _____ (deliver/significant/efficiency/gain) within the _____ _____ (first/two) _____ (year) — that it _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (clearly/has/not/do/so/suggests/that/something) _____ _____ _____ _____ _____ _____ _____ _____ (has/gone/wrong) either in its _____ _____ _____ _____ _____ _____ _____ _____ (design/or/in/its/implementation).','reform / was supposed to / deliver significant efficiency gains / first two / years / clearly has not done so suggests that something / has gone wrong / design or in its implementation',NULL,'''Was supposed to deliver'' (expectation not met); ''has not done so suggests something has gone wrong'' (result/inference).','hard'),
  (cid,77,253,'gap_fill','This _____ (outcome) _____ _____ _____ (be/bound/to) _____ (generate) _____ _____ (controversy) — anyone with _____ (knowledge/of) the _____ (political) _____ (landscape) _____ (would/foresee) that _____ (stakeholder) with _____ (competing) _____ (interest) _____ (would/resist) the _____ (change) and that _____ (managing) this _____ (resistance) _____ (would/require) _____ (considerable) _____ (diplomatic) _____ (skill).','outcome / was bound to / generate / controversy / knowledge of / political / landscape / would have foreseen / stakeholders / competing / interests / would resist / change / managing / resistance / would require / considerable / diplomatic / skill',NULL,'''Was bound to generate controversy'' = inevitability (semi-modal); ''would have foreseen / would resist / would require'' = third conditional results.','hard'),
  (cid,77,254,'gap_fill','The _____ (organization) _____ (need/to) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (not/merely/update/its/formal/procedure) but _____ (fundamentally) _____ (rethink) the _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (incentive/structure/that/drive/the/behavior/of/its/staff).','organization / needs to / not merely update its formal procedures / fundamentally / rethink / incentive structures that drive the behavior of its staff',NULL,'''Needs to not merely update but fundamentally rethink'' = semi-modal (need to) with emphatic contrast.','hard'),
  (cid,77,255,'gap_fill','Given the _____ (scale) of the _____ _____ (challenge), it _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (does/not/have/to/be/this/way) — _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (with/the/right/combination/of/political/will/and/technical/capacity), _____ (significant) _____ _____ (improvement) _____ _____ _____ _____ _____ _____ _____ _____ _____ (are/bound/to/be/achievable).','scale / challenge / does not have to be this way / with the right combination of political will and technical capacity / significant / improvements / are bound to be achievable',NULL,'''Does not have to be this way'' (absence of obligation); ''bound to be achievable'' (near certainty/inevitability, semi-modal).','hard'),
  (cid,77,256,'gap_fill','The _____ (committee) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (was/supposed/to/publish/its/recommendation) by the _____ _____ _____ _____ _____ _____ (end/of/the) _____ _____ _____ _____ (financial/year) — the _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (delay/is/bound/to/generate/speculation) about the _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (political/reason/for/the/postponement).','was supposed to publish its recommendations / end of the / financial year / delay is bound to generate speculation / political reasons for the postponement',NULL,'''Was supposed to publish'' (unfulfilled expectation); ''is bound to generate speculation'' (inevitable consequence, semi-modal).','hard'),
  (cid,77,257,'gap_fill','Any _____ _____ (comprehensive) _____ (account) of the _____ (phenomenon) _____ _____ (has/to) _____ (engage) _____ _____ (seriously) with _____ _____ _____ (competing/theoretical) _____ (perspective) — a _____ (study) _____ (that/fails/to) _____ (do) so _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (is/bound/to/oversimplify) the _____ _____ _____ (complexity/of/the) _____ (empirical) _____ (reality).','comprehensive / account / phenomenon / has to / engage / seriously / competing theoretical / perspectives / study / that fails to / do so / is bound to oversimplify / complexity of the / empirical / reality',NULL,'''Has to engage seriously'' (strong necessity); ''is bound to oversimplify'' (inevitable consequence).','hard'),
  (cid,77,258,'multiple_choice','Which sentence CORRECTLY uses ''be supposed to'' to express an unfulfilled expectation?','The independent review was supposed to conclude by December, but it has yet to submit its final report.','[''The independent review is supposed to have concluded by December.'',''The independent review was supposed to conclude by December, but it has yet to submit its final report.'',''The independent review was supposed to concluding by December.'',''The independent review supposed to conclude by December.'']','Option B: ''was supposed to + base verb'' = unfulfilled expectation in the past. ''Is supposed to have concluded'' (A) = present perfect — different time reference; ''was supposed to concluding'' (C) = ungrammatical; ''supposed to'' (D) = missing ''was.''','easy'),

  -- BLOCK 78: Negative modals — mustn't vs needn't vs can't vs shouldn't (8 ex)
  (cid,78,259,'gap_fill','Researchers _____ (mustn''t) _____ (allow) their _____ _____ (prior) _____ (theoretical) _____ (commitment) to _____ _____ _____ _____ (distort/the/collection/and) _____ (interpretation) of _____ (data) — but they _____ (needn''t) _____ (approach) their _____ (subject) without _____ (any) _____ (theoretical) _____ (framework) at all, since _____ (pure) _____ (atheoretical) _____ (description) is _____ (rarely) _____ (informative).','mustn''t / allow / prior / theoretical / commitments / distort the collection and / interpretation / data / needn''t / approach / subject / theoretical / framework / atheoretical / description / rarely / informative',NULL,'''Mustn''t'' = prohibition; ''needn''t'' = absence of necessity (don''t need to but it''s fine either way). Key contrast in academic methods.','medium'),
  (cid,78,260,'gap_fill','The _____ (finding) _____ (can''t) _____ (interpret/passive) as _____ (definitive) _____ (evidence) of a _____ _____ _____ _____ _____ _____ (causal/relationship/without/addressing) the _____ _____ _____ _____ (threat/of/confounding) — nor _____ (should) they _____ (take/passive) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (as/merely/suggestive/evidence/that/demands/no/further/investigation).','findings / can''t be interpreted / definitive / evidence / causal relationship without addressing / threat of confounding / should / be taken / as merely suggestive evidence that demands no further investigation',NULL,'''Can''t be interpreted'' = impossibility/prohibition; ''should not be taken'' = recommendation against.','hard'),
  (cid,78,261,'gap_fill','You _____ (mustn''t) _____ (confuse) _____ (correlation) with _____ (causation), but you _____ (needn''t) _____ (discount) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (observational/evidence/entirely/simply/because) it _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (cannot/satisfy/the/gold/standard) of _____ _____ _____ _____ _____ _____ (randomized/controlled/trial).','mustn''t / confuse / correlation / causation / needn''t / discount / observational evidence entirely simply because / cannot satisfy the gold standard / randomized controlled trial',NULL,'''Mustn''t confuse'' (prohibition) vs ''needn''t discount'' (no requirement to dismiss entirely); methodological nuance.','hard'),
  (cid,78,262,'gap_fill','The _____ (government) _____ (shouldn''t) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (commit/itself/to/a/target/it) _____ (can''t/realistically) _____ (achieve) within the _____ _____ _____ _____ _____ _____ (specified/timeframe) — _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (credibility/once/lost/needn''t) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (take/decades/to/rebuild).','government / shouldn''t / commit itself to a target it / can''t realistically / achieve / specified timeframe / credibility once lost needn''t / take decades to rebuild',NULL,'''Shouldn''t commit'' (advice against); ''can''t achieve'' (impossibility); ''needn''t take decades'' (absence of necessity for pessimism).','hard'),
  (cid,78,263,'gap_fill','_____ (Policy) _____ _____ (maker) _____ (mustn''t) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (treat/the/outputs/of/formal/modelling/exercises/as/a/substitute) for _____ _____ _____ _____ _____ (sound/political) _____ _____ _____ _____ _____ (judgment) — models can''t _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (capture/the/full/complexity/of/political/reality/and/shouldn''t/be/used/as/though/they/could).','Policy / makers / mustn''t / treat the outputs of formal modelling exercises as a substitute / sound political / judgment / capture the full complexity of political reality and shouldn''t be used as though they could',NULL,'''Mustn''t treat models as substitute for judgment'' + ''can''t capture full complexity'' + ''shouldn''t be used as though they could.''','hard'),
  (cid,78,264,'gap_fill','The _____ _____ (committee) _____ (shouldn''t) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (reach/a/conclusion/it/cannot/defend/publicly) — but it _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (needn''t/confine/its/recommendation/to/what/is/immediately/politically/feasible).','committee / shouldn''t / reach a conclusion it cannot defend publicly / needn''t confine its recommendations to what is immediately politically feasible',NULL,'''Shouldn''t reach'' (advice against prohibition); ''needn''t confine'' (absence of necessity — can be bolder than the politically immediate).','hard'),
  (cid,78,265,'gap_fill','The _____ (absence) of _____ (statistically) _____ (significant) _____ (result) _____ (mustn''t) _____ (interpret/passive) as _____ _____ (evidence/of) _____ _____ _____ _____ _____ (absence/of/effect) — it _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (can''t/simply/mean/that/the/study/was/insufficiently/powered) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (to/detect/an/effect/that/in/fact/exists).','absence / statistically / significant / results / mustn''t be interpreted / evidence of / absence of effect / can''t simply mean that the study was insufficiently powered / to detect an effect that in fact exists',NULL,'''Mustn''t be interpreted as evidence of absence'' = prohibition; ''can''t simply mean the study was underpowered'' = epistemic impossibility. Null results in research.','hard'),
  (cid,78,266,'multiple_choice','What is the key difference between ''mustn''t'' and ''needn''t'' in formal English?','Mustn''t expresses prohibition (it is forbidden), while needn''t expresses absence of necessity (it is not required but not forbidden).','[''Both express prohibition equally'',''Mustn''t expresses absence of necessity while needn''t expresses prohibition'',''Mustn''t expresses prohibition (it is forbidden), while needn''t expresses absence of necessity (it is not required but not forbidden).'',''They are interchangeable in all formal contexts'']','Option C: ''mustn''t'' = prohibition (you are not allowed); ''needn''t'' = absence of necessity (you don''t have to, but you may if you wish).','easy'),

  -- BLOCK 79: TOEFL Reading — Advanced Modals (8 ex)
  (cid,79,267,'multiple_choice','[TOEFL Reading] ''The anomaly must have been introduced during processing.'' This expresses:','a strong logical deduction about a past event based on available evidence.','[''a recommendation about what should be done'',''a strong logical deduction about a past event based on available evidence.'',''a possibility that the anomaly might have been introduced'',''a criticism of what was done incorrectly'']','Option B: ''must have been + past participle'' = epistemic modal (past deduction). Not recommendation (should), not possibility (might), not criticism (should have).','easy'),
  (cid,79,268,'gap_fill','[TOEFL Reading] ''The committee _____ (should/consult) more widely before proceeding.'' This type of ''should have'' expresses:','should have consulted / past criticism (the action should have happened but did not)',NULL,'''Should have consulted'' = past criticism/regret — the action did not happen and the writer believes it should have.','medium'),
  (cid,79,269,'gap_fill','[TOEFL Reading] ''The outcome _____ (could/be) different had the initial conditions differed.'' This is:','could have been / a past counterfactual — expressing an unrealized past possibility',NULL,'''Could have been different had...'' = third conditional counterfactual.','medium'),
  (cid,79,270,'gap_fill','[TOEFL Reading] ''The reform _____ (be/supposed/to) deliver efficiency gains but has not done so.'' ''Was supposed to'' indicates:','was supposed to / an unfulfilled past expectation or intention',NULL,'''Was supposed to deliver'' = expectation that was set but not fulfilled — the semi-modal ''be supposed to'' expresses a prior arrangement or expectation.','medium'),
  (cid,79,271,'gap_fill','[TOEFL Reading] ''The pattern _____ (may/indicate) a structural shift.'' vs ''All researchers _____ (must/follow) ethical protocols.'' Distinguish:','may indicate / must follow / ''may indicate'' is epistemic (uncertainty about truth); ''must follow'' is deontic (obligation)',NULL,'Epistemic ''may'' = uncertain proposition; deontic ''must'' = obligation/necessity. Same surface form, different function.','medium'),
  (cid,79,272,'gap_fill','[TOEFL Reading] ''The team _____ (must/work) under considerable pressure given the pace of output.'' What does ''must be working'' express?','must be working / a present epistemic deduction about an ongoing activity',NULL,'''Must be working'' = modal progressive expressing strong inference about what is currently happening.','medium'),
  (cid,79,273,'gap_fill','[TOEFL Reading] ''Researchers _____ (mustn''t) confuse correlation with causation, but they _____ (needn''t) discard observational evidence entirely.'' The difference is:','mustn''t / needn''t / ''mustn''t'' = prohibition; ''needn''t'' = absence of necessity (no need to but it is not forbidden)',NULL,'Mustn''t = forbidden; needn''t = not required. Critical distinction for academic reading.','medium'),
  (cid,79,274,'multiple_choice','[TOEFL Reading] ''The situation was bound to generate controversy.'' The phrase ''was bound to'' means:','it was inevitable that the situation would generate controversy.','[''it was obligated to generate controversy'',''the situation was tied to controversy'',''it was inevitable that the situation would generate controversy.'',''the situation needed to generate controversy'']','Option C: ''be bound to'' = inevitability (near-certain future/past result). Not the same as obligation or need.','easy'),

  -- BLOCK 80: TOEFL Speaking — Advanced Modals (8 ex)
  (cid,80,275,'production','[TOEFL Speaking — 45s] Summarize the reading on governance reform using advanced modals.','',NULL,'The reading argues that the failure of governance reform efforts must have resulted from a combination of poor design and inadequate implementation — it could not simply be attributed to bad luck or unfavorable external conditions. According to the reading, reformers should have invested more in consultation and capacity building before launching the initiative, and the oversight mechanisms that were supposed to detect and correct problems must have been functioning inadequately. The reading suggests that better-designed reforms might have achieved far greater impact and that the resources needlessly spent on poorly targeted interventions could have been more productively deployed elsewhere. It concludes that similar failures are bound to recur unless policymakers develop a more rigorous approach to reform design.','hard'),
  (cid,80,276,'production','[TOEFL Speaking — 45s] The professor challenges the reading. Use advanced modals throughout.','',NULL,'The professor argues that the reading must be oversimplifying a complex phenomenon and that the policy failures it describes cannot simply be attributed to poor design. She insists that the reading should have engaged more seriously with the literature on political economy and that it needn''t have focused so heavily on technical design at the expense of the political dimensions of reform. The professor suggests that the reforms might have succeeded under different political conditions and that policymakers cannot be expected to achieve better outcomes without addressing the underlying incentive problems that must be driving their behavior. She concludes that the reading was supposed to provide a comprehensive account but has instead offered only a partial one.','hard'),
  (cid,80,277,'production','[TOEFL Speaking — 60s] Compare the reading and professor using advanced modals throughout.','',NULL,'Both the reading and the professor agree that governance reform has been less successful than it should have been, though they disagree sharply about why. The reading argues that the failures must have resulted from poor technical design and that better-designed reforms could have achieved considerably greater impact. It suggests that the oversight mechanisms that were supposed to detect and correct problems must have been malfunctioning and that reformers should have invested more in evidence-based design. The professor challenges this account, arguing that the reading cannot be offering a complete explanation when it ignores the political economy in which reforms must operate. She insists that technical design improvements, however well-intentioned, needn''t produce better outcomes if the underlying political incentives are misaligned, and that any future reform effort is bound to face similar problems unless these incentives are addressed. The synthesis of these perspectives suggests that governance reform must be understood as a challenge requiring both technical and political solutions — neither dimension can be ignored, and an approach that neglects either one is bound to disappoint. Future practitioners should have learned this lesson from the record of past failures, and they mustn''t repeat the same mistakes in designing the next generation of reform initiatives.','hard'),
  (cid,80,278,'gap_fill','[TOEFL Speaking] The reading argues that reformers _____ _____ _____ _____ _____ (should/consult/more/widely) and that the _____ _____ _____ _____ _____ (failure/might/avoid/passive) had they _____ _____ _____ _____ _____ (done/so/earlier).','should have consulted more widely / failure might have been avoided / done so earlier',NULL,'''Should have consulted'' (past criticism) + ''might have been avoided'' (past passive counterfactual).','hard'),
  (cid,80,279,'gap_fill','[TOEFL Speaking] The professor insists the reading _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (must/be/oversimplifying) the _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (political/dimension/of/the/reform/challenge).','must be oversimplifying / political dimensions of the reform challenge',NULL,'''Must be oversimplifying'' = present epistemic progressive deduction (present criticism based on evidence).','hard'),
  (cid,80,280,'gap_fill','[TOEFL Speaking] Synthesizing: both agree that governance reform _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (needn''t/fail/but) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (is/bound/to/if/either/technical/or/political/dimensions/are/neglected).','needn''t fail but / is bound to if either technical or political dimensions are neglected',NULL,'''Needn''t fail'' (absence of necessity) vs ''is bound to'' (inevitability when key conditions are absent).','hard'),
  (cid,80,281,'gap_fill','[TOEFL Speaking] According to the professor, reformers _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (mustn''t/assume/that/technical/design/improvements/alone) _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (can/deliver/sustainable/governance/improvement).','mustn''t assume that technical design improvements alone / can deliver sustainable governance improvement',NULL,'''Mustn''t assume'' (prohibition against overconfidence) + ''can deliver'' (capability modal).','hard'),
  (cid,80,282,'multiple_choice','[TOEFL Speaking] Which sentence MOST effectively demonstrates mastery of advanced modals for TOEFL Speaking?','The reforms should have been designed with greater attention to political economy, since better-designed initiatives might have achieved far more durable outcomes.','[''The reforms were bad and didn''t work well.'',''The reforms should have been designed with greater attention to political economy, since better-designed initiatives might have achieved far more durable outcomes.'',''We think the reforms could maybe have been done differently.'',''The reforms, which should have worked better, didn''t.'']','Option B: ''should have been designed'' (past criticism, passive) + ''might have achieved'' (past counterfactual) = two advanced modal forms in an integrated, coherent sentence.','medium'),

  -- BLOCK 81: TOEFL Writing — produção (9 ex)
  (cid,81,283,'production','[TOEFL Writing — 200 words] Explain what the reading and the lecture argue using advanced modals.','',NULL,'The reading and the lecture both engage with the question of why governance reform so frequently fails to deliver on its promise, and both make extensive use of modal language to express their respective analyses and recommendations. The reading argues that past reform efforts must have been insufficiently grounded in empirical evidence and that better-designed initiatives could have achieved considerably more durable outcomes. It suggests that reformers should have invested more heavily in consultation and capacity building and that the oversight mechanisms that were supposed to ensure accountability must have been malfunctioning. The lecture challenges this account by insisting that the reading must be underestimating the role of political economy in determining reform outcomes. The professor argues that technically well-designed reforms needn''t succeed if the underlying political incentives are misaligned and that failure in such circumstances is bound to recur regardless of how much effort is invested in improving formal design. The synthesis of these perspectives suggests that future reform efforts mustn''t treat technical and political dimensions as separable and that practitioners should have learned this lesson from the accumulated evidence of past failures. Only by attending simultaneously to both dimensions can reform efforts hope to move beyond the cycle of well-intentioned initiatives that were supposed to deliver fundamental change but ultimately did not.','hard'),
  (cid,81,284,'gap_fill','[TOEFL Writing] The reading argues that the failure _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (must/have/result/passive/from/poor/design) and that better outcomes _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (could/have/achieve/passive) with a more _____ _____ _____ _____ _____ _____ (evidence-based/approach).','must have resulted from poor design / could have been achieved / evidence-based approach',NULL,'''Must have resulted'' (past deduction) + ''could have been achieved'' (past passive counterfactual).','hard'),
  (cid,81,285,'gap_fill','[TOEFL Writing] The professor insists that technically well-designed reforms _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (needn''t/succeed) without _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (accompanying/political/economy/reform) and that failure _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (is/bound/to/recur) without it.','needn''t succeed / accompanying political economy reform / is bound to recur',NULL,'''Needn''t succeed'' (absence of necessity for success) + ''is bound to recur'' (inevitability of failure).','hard'),
  (cid,81,286,'gap_fill','[TOEFL Writing] Both the reading and the professor agree that past reform practitioners _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (should/have/been/more/attentive/to/the/political/conditions/necessary/for/sustained/reform) and that future _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (practitioners/mustn''t/repeat/these/mistakes).','should have been more attentive to the political conditions necessary for sustained reform / practitioners mustn''t repeat these mistakes',NULL,'''Should have been more attentive'' (past criticism) + ''mustn''t repeat'' (present prohibition for future action).','hard'),
  (cid,81,287,'gap_fill','[TOEFL Writing] The reading concludes that better-designed reforms _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (might/have/achieve/passive/far/greater/durable/change) while the professor argues that such reforms _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (needn''t/have/succeed/without/addressing/political/economy).','might have achieved far greater durable change / needn''t have succeeded without addressing political economy',NULL,'''Might have achieved'' (counterfactual optimism) vs ''needn''t have succeeded'' (skepticism about technical design alone).','hard'),
  (cid,81,288,'gap_fill','[TOEFL Writing] The professor argues that reformers _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (must/be/underestimating) the _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (role/of/political/incentives) in _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (determining/reform/outcomes).','must be underestimating / role of political incentives / determining reform outcomes',NULL,'''Must be underestimating'' = present epistemic modal progressive (professor''s deduction about the reading''s blind spot).','hard'),
  (cid,81,289,'gap_fill','[TOEFL Writing] The synthesis of the reading and lecture suggests that governance reform _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ _____ (needn''t/fail/but/is/bound/to/without/simultaneous/attention/to/both/technical/and/political/dimensions).','needn''t fail but is bound to without simultaneous attention to both technical and political dimensions',NULL,'''Needn''t fail'' (no necessity for failure) + ''is bound to'' (inevitable if conditions absent) = capstone modal contrast.','hard'),
  (cid,81,290,'production','[TOEFL Writing — 200 words] Write a body paragraph using advanced modals throughout.','',NULL,'The record of past governance reform efforts suggests several conclusions about what future practitioners mustn''t do and what they need to do differently. They mustn''t treat technical design as a substitute for political strategy, since even the most carefully designed reform is bound to fail if it lacks the political support needed for sustained implementation. They should have learned from the failures of the past that reforms supposed to deliver transformation in the short term almost invariably prove to be overly optimistic and that more modest, incremental approaches might have achieved more durable results. Future reformers need to invest more heavily in the political economy of reform — in building coalitions, managing opposition, and creating incentives aligned with the behavior they seek to promote. They needn''t abandon formal institutional design, which remains important, but they must not treat it as sufficient. The evidence suggests that reforms that were supposed to deliver fundamental change and did not must have failed for identifiable reasons that could have been avoided with better analysis and design. The field cannot continue to repeat these failures — something must be changing in how we approach reform, and it must be changing fast, or the next generation of reforms is bound to disappoint in the same ways as those that came before.','hard'),
  (cid,81,291,'multiple_choice','[TOEFL Writing] Which sentence MOST effectively demonstrates integration of advanced modals?','The reforms should have been designed with closer attention to implementation capacity, since better-prepared initiatives might have achieved far more durable outcomes and needn''t have been abandoned before their objectives were reached.','[''The reforms were not good and should be better.'',''The reforms should have been designed with closer attention to implementation capacity, since better-prepared initiatives might have achieved far more durable outcomes and needn''t have been abandoned before their objectives were reached.'',''The reforms didn''t work and must be improved.'',''Better reforms could maybe have been done.'']','Option B: ''should have been designed'' + ''might have achieved'' + ''needn''t have been abandoned'' = three distinct advanced modal forms in one integrated, coherent sentence.','medium'),

  -- BLOCK 82: Production avançada — capstone (9 ex)
  (cid,82,292,'production','[TOEFL Writing — 200 words] Capstone: Write a conclusion on advanced modals in governance discourse.','',NULL,'The governance reform literature makes extensive use of the full range of modal auxiliaries because the domain is inherently one of both uncertainty and obligation — of what is (epistemic modality) and what ought to be (deontic modality). When analysts write that past reforms must have failed for identifiable reasons, they are expressing confident deductions from available evidence. When they argue that better-designed initiatives might have achieved more durable outcomes, they are exploring unrealized past possibilities. When they insist that future reformers mustn''t repeat past mistakes and that evidence-based design should be adopted, they are expressing obligations and recommendations. And when they observe that reform failures are bound to recur unless underlying incentive problems are addressed, they are expressing near-certain predictions about future states of the world. Mastery of these modal distinctions — between epistemic and deontic, between past deduction and past counterfactual, between prohibition and absence of necessity — is essential for reading academic texts in this domain and for producing the kind of nuanced, hedged analysis that the genre requires. The students who most effectively demonstrate this mastery in their TOEFL writing are those who have developed an intuitive sense not merely of the grammatical forms involved but of the epistemic and normative commitments that each form carries with it.','hard'),
